def slug(text):
    result = []
    last_was_hyphen = False
    for char in text:
        lower_char = char.lower()
        if ('a' <= lower_char <= 'z') or lower_char.isdigit():
            result.append(lower_char)
            last_was_hyphen = False
        else:
            if not last_was_hyphen:
                result.append('-')
                last_was_hyphen = True
    s = ''.join(result)
    return s.strip('-')

import re

def slug(text):
    text = text.lower()
    text = re.sub(r'[^a-z0-9]+', '-', text)
    return text.strip('-')
